import {ROLES,MODES,defaultWorkspace,buildPrompt,evaluateReply,validateImport} from './engine.js';
const QA=new URLSearchParams(location.search).get('qa')==='1';
const KEY=QA?'glam-tiktok-qa-workspace-v1':'glam-tiktok-workspace-v1', $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID(), now=()=>new Date().toISOString(), clone=x=>JSON.parse(JSON.stringify(x));
let ws=defaultWorkspace(), storageError='', view='home', subtab='brand', formStep=0, selectedRole='scout', editJob=null, currentJob=null, intake={}, filters={}, pendingImport=null, toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw)ws=validateImport(JSON.parse(raw),defaultWorkspace());}catch(e){storageError='Your saved workspace could not be loaded. The original browser data is preserved. Export a recovery copy in Settings before continuing.';}
for(const k of ['jobs','prompts','assets','characters','engagement','suppression','activity'])ws[k]??=[];
ws.settings??={};ws.brand??={};
const navs=[['home','Home'],['intake','Content intake'],['vault','Content vault'],['solo','Solo agents'],['chat','AI Chat'],['queue','Queue & review'],['engagement','Engagement & VAULT'],['settings','Settings']];
const sources=['New idea','Existing TikTok','My uploaded content','Saved research','Audience question'], goals=['Teach','Start a conversation','Show a process','Answer a question','Invite interest in the Glam Vault'], formats=['Talking head','Screen recording','Voiceover with visuals','B-roll','Carousel plan','Another format'], ctas=['No CTA','Ask a question','Invite a save/share','DM VAULT for details','Custom approved wording'];
const fields={title:['Job title','text','Give this idea a name'],source:['Content source','select',sources],sourceText:['Source link, file reference, or notes','textarea','Paste the exact context. References are not uploaded attachments.'],rights:['Rights and ownership','select',['Mine','Licensed to use','Research reference only','Needs checking']],mode:['Content mode','select',MODES.map(m=>[m.id,m.name])],goal:['Main goal','select',goals],topic:['Topic','text','What are we talking about?'],takeaway:['One useful takeaway','textarea','What should someone understand or be able to do?'],audience:['Who is this for?','text','Beginners learning AI prompts'],format:['Video format','select',formats],length:['Target length','text','30–60 seconds'],tone:['Voice and tone','text','Friendly, clear, confident, and helpful'],visual:['Visual approach','select',['Use existing assets','Real footage','Optional generated visuals','No new visuals']],character:['Optional character reference','text','Approved reference name or ID, if needed'],presentation:['Product presentation','select',['Not applicable','On-screen demo','Holding a physical item','Wearing a physical item']],cta:['Call to action','select',ctas],customCTA:['Exact custom CTA','textarea','Only wording you have approved'],productName:['Product name','text','Glam Vault'],productLink:['Verified public product link','url','https://payhip.com/b/54LoK'],date:['Intended posting date','date',''],timezone:['Timezone','text','Your posting timezone'],notes:['Notes, disclosures, and anything to avoid','textarea','Planning only. No automatic posting or sending.'],researchQuestion:['Research question','textarea','What needs to be checked?'],sourcesToCheck:['Sources to check','textarea','Exact links and source dates when known'],assetRefs:['Available assets / attachment list','textarea','List files you will attach separately in chat'],visualGoal:['Visual goal','textarea','The simplest way to show this idea'],restrictions:['Visual restrictions','textarea','What should not change or appear?'],hookDirection:['Hook direction','textarea','What should the opening communicate?'],sourceFacts:['Supported source facts','textarea','Facts with references. Leave unknown claims marked for checking.'],approvedScript:['Approved script','textarea','Paste the exact script you want to work from'],editingNotes:['Editing notes','textarea','Pacing, captions, cuts, audio'],destinationAccount:['Destination account','text','@promptlikeglam'],requestedOutput:['What do you want back?','textarea','A manual checklist, caption, shot list, or other precise outcome'],replyContext:['Exact caption / comment / DM context','textarea','Paste only the minimum context needed. No secrets or sensitive details.'],recipient:['Intended recipient, if applicable','text','Platform handle, not a full private profile']};
const getMode=id=>MODES.find(m=>m.id===id)?.name||id||'Not selected', getRole=id=>ROLES.find(r=>r.id===id)?.name||(id==='full'?'All five roles':id||'All five roles');
function dateText(s){if(!s)return'Not recorded';const d=new Date(s);return Number.isNaN(d.getTime())?'Not recorded':d.toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
function safeURL(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return'';}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(message='Saved in this browser'){if(storageError){toast('Storage is protected. Export a recovery copy and reload before making changes.');return false;}try{localStorage.setItem(KEY,JSON.stringify(ws));$('#save-status').textContent=`${message} · ${new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`;return true;}catch(e){toast('Browser storage is full or unavailable. Download a backup now.');$('#save-status').textContent='Not saved. Export a backup in Settings.';return false;}}
function log(action,itemId='',result='Saved'){ws.activity.unshift({id:uid(),action,itemId,time:now(),result});ws.activity=ws.activity.slice(0,300);}
function download(name,text,type='text/plain'){window.__saveOut(name,text);}
function filename(title,ext='txt'){return`${String(title||'glam-workspace').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,70)}-${new Date().toISOString().slice(0,10)}.${ext}`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Paste it into your chat or manual workflow.');}catch{modal('Copy your text',`<p class="form-note">Clipboard access is unavailable. Select and copy the text below.</p><textarea id="copy-fallback" readonly>${esc(text)}</textarea>`);$('#copy-fallback').select();}}
function modal(title,body){$('#dialog-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="btn small" data-action="close-dialog" aria-label="Close dialog">Close</button></div><div class="modal-body">${body}</div>`;$('#dialog').showModal();}
function closeModal(){$('#dialog').close();}
function button(text,action,id='',className=''){return`<button class="btn ${className}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${esc(text)}</button>`;}
function empty(title,body,action,label){return`<div class="empty"><h3>${esc(title)}</h3><p>${esc(body)}</p>${action?button(label,action):''}</div>`;}
function heading(kicker,title,desc,extra=''){return`<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${extra}</div>`;}
function badge(status){return`<span class="badge ${status==='Ready'||status==='Complete'?'ready':status.includes('Review')?'review':status.includes('Human')||status==='Blocked'?'blocked':''}">${esc(status)}</span>`;}
function field(key,values={},wide=false){const [label,type,opts]=fields[key]||[key,'textarea',''];const v=values[key]??'';let control;if(type==='select')control=`<select name="${key}" id="f-${key}">${opts.map(o=>{let [value,name]=Array.isArray(o)?o:[o,o];return`<option value="${esc(value)}" ${v===value?'selected':''}>${esc(name)}</option>`;}).join('')}</select>`;else if(type==='textarea')control=`<textarea name="${key}" id="f-${key}" placeholder="${esc(opts)}">${esc(v)}</textarea>`;else control=`<input type="${type}" name="${key}" id="f-${key}" value="${esc(v)}" placeholder="${esc(opts)}">`;return`<label class="field ${wide?'wide':''}">${esc(label)}${control}</label>`;}
function collect(form){return Object.fromEntries(new FormData(form).entries());}
function jobDefaults(){return {source:'New idea',rights:'Mine',mode:MODES[0].id,goal:'Teach',format:'Screen recording',length:'30–60 seconds',tone:'Friendly, clear, confident, and helpful',audience:ws.brand.audience||'Beginners learning AI prompts',visual:'Use existing assets',presentation:'Not applicable',cta:'No CTA',productName:'Glam Vault',productLink:ws.brand.productLink||'https://payhip.com/b/54LoK',destinationAccount:'@promptlikeglam'};}
function show(next,opts={}){if(view==='detail'&&$('#job-output')){const current=ws.jobs.find(x=>x.id===currentJob);if(current&&$('#job-output').value!==current.output&&!opts.__ok){window.__ask('You have unsaved output edits. Leave this screen without saving them?').then(ok=>{if(ok)show(next,{...opts,__ok:true});});return;}}if(view==='intake'||view==='solo'){const f=$('#job-form');if(f)intake={...intake,...collect(f)};}view=next;if(opts.fresh){intake=jobDefaults();formStep=0;editJob=null;}if(opts.job)currentJob=opts.job;if(opts.tab)subtab=opts.tab;render();$('#main').scrollTop=0;}
function render(){document.title=`${navs.find(n=>n[0]===view)?.[1]||'Review'} · Glam TikTok Agent Farm`;$('#nav').innerHTML=navs.map(([id,name],i)=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}"><span class="num">0${i+1}</span>${name}</button>`).join('');$('#breadcrumb').textContent=`Your workspace / ${view==='detail'?'Job review':navs.find(n=>n[0]===view)?.[1]||view}`;$('#main').innerHTML=(QA?'<div class="notice warning">Isolated test workspace. Synthetic test records stay separate from your real workspace.</div>':'')+(storageError?`<div class="notice danger">${esc(storageError)}</div>`:'')+({home:home,intake:intakeView,solo:soloView,queue:queueView,detail:detailView,vault:vaultView,engagement:engagementView,settings:settingsView,chat:aiChatView}[view]||home)();}
function home(){let active=ws.jobs.filter(j=>!j.archived),next=active.find(j=>j.progress!=='Complete');return`<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR NEXT GOOD IDEA STARTS HERE</div><h1>A little structure.<br>A lot more creating.</h1><p>One calm place for your TikTok ideas, content packages, and conversations. Pick a starting point. Make something useful.</p><button class="btn primary" data-action="new-content">Create content <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="paper-stack"><div class="mini-label">GLAM / CREATOR NOTES</div><div class="mini-title">Idea.<br>Make it clear.<br>Make it yours.</div><div class="mini-line"></div><div class="mini-foot">9:16 · @promptlikeglam</div></div><div class="art-label">FROM FIRST THOUGHT TO READY</div></div></section><div class="cards-3"><button class="start-card" data-action="new-content"><div class="card-top"><span>01</span><span>↗</span></div><h3>Create content</h3><p>Turn a real idea into a clear plan.</p></button><button class="start-card" data-view="queue"><div class="card-top"><span>02</span><span>↗</span></div><h3>Work my queue</h3><p>Pick up where you left off.</p></button><button class="start-card" data-view="engagement"><div class="card-top"><span>03</span><span>↗</span></div><h3>Draft a reply</h3><p>Helpful first. Always human-reviewed.</p></button></div><div class="numbers"><div class="number"><strong>${active.length}</strong><span>ACTIVE CONTENT JOBS</span></div><div class="number"><strong>${active.filter(j=>j.status==='Needs Review').length}</strong><span>WAITING FOR REVIEW</span></div><div class="number"><strong>${ws.engagement.filter(e=>!['Sent Verified','Failed'].includes(e.state)).length}</strong><span>REPLY DRAFTS & REVIEWS</span></div></div><div class="two-col"><section><div class="section-title"><h2>Your next step</h2><button class="text-button" data-view="queue">See queue ↗</button></div>${next?jobCard(next):empty('A clean slate.','Save your first idea. You can fill in the details later.','new-content','Start a draft')}</section><section><div class="section-title"><h2>Connected to your process</h2><span class="tag">NOT YOUR ACCOUNTS</span></div><div class="panel"><div class="row"><h3>AI-assisted workspace</h3><span class="badge">Secure AI chat</span></div><p>AI Chat drafts and revises with your selected job context. Run in Chat still prepares a prompt to copy. Nothing posts or sends automatically.</p><div class="actions mt"><button class="text-button" data-action="how-it-works">Meet your five roles ↗</button><button class="text-button" data-view="settings">Connection details ↗</button></div></div></section></div>`;}
function intakeView(){if(!Object.keys(intake).length)intake=jobDefaults();const groups=[['title','source','sourceText','rights','mode','goal','topic','takeaway','audience'],['format','length','tone','visual','character','presentation','assetRefs'],['cta','customCTA','productName','productLink','date','timezone','notes']];return heading('CONTENT INTAKE',editJob?'Refine your idea.':'Let’s make it useful.','Start with what you have. Missing details never stop you saving a draft.')+`<div class="tabs">${['01 / The idea','02 / Creative direction','03 / Finish & CTA'].map((s,i)=>`<button class="tab ${i===formStep?'active':''}" data-action="form-step" data-id="${i}">${s}</button>`).join('')}</div><form id="job-form" class="panel"><div class="form-grid">${groups[formStep].map(k=>field(k,intake,['sourceText','takeaway','assetRefs','notes','customCTA'].includes(k))).join('')}</div><div class="form-footer"><small class="muted">Saved inputs stay separate from returned work.<br>Planning dates do not schedule a post.</small><div class="actions">${button('Save draft','save-job','', '')}${formStep<2?button('Next step →','form-step',String(formStep+1),'primary'):button('Save & open job','save-open','','primary')}</div></div></form>`;}
function soloView(){const r=ROLES.find(r=>r.id===selectedRole)||ROLES[0];if(!Object.keys(intake).length)intake=jobDefaults();const special={scout:['topic','sourceText','mode','audience','researchQuestion','sourcesToCheck'],visual:['format','assetRefs','character','visualGoal','presentation','restrictions','mode'],script:['takeaway','hookDirection','length','format','sourceFacts','cta','mode'],production:['approvedScript','assetRefs','editingNotes','destinationAccount','requestedOutput','mode'],conversation:['replyContext','recipient','requestedOutput','cta','productName','productLink','sourceFacts','mode']};return heading('SOLO AGENT FORMS','One task. The right role.','Just need hooks, a script, or a reply? Prepare a focused handoff, not the whole workflow.')+`<div class="role-grid">${ROLES.map((r,i)=>`<button class="role-card ${selectedRole===r.id?'active':''}" data-action="select-role" data-id="${r.id}">0${i+1}<strong>${esc(r.short||r.name)}</strong><span>Prepare a prompt ↗</span></button>`).join('')}</div><form id="job-form" class="panel"><div class="section-title" style="margin-top:0"><h2>${esc(r.name)}</h2><span class="tag">MANUAL HANDOFF</span></div><p class="form-note" style="margin:0 0 20px">${esc(r.description)}</p><div class="form-grid">${['title',...special[r.id]].map(k=>field(k,intake,['sourceText','approvedScript','replyContext','sourceFacts'].includes(k))).join('')}</div><div class="form-footer"><small class="muted">No AI service runs in this dashboard.</small><div class="actions">${button('Save draft','save-job')}${button('Create handoff','save-handoff','','primary')}</div></div></form>`;}
function saveJob(open=false,handoff=false){const form=$('#job-form');intake={...intake,...collect(form)};let j=ws.jobs.find(j=>j.id===editJob);if(j){snapshot(j);j.fields=clone(intake);j.title=intake.title.trim()||'Untitled idea';j.updatedAt=now();outputChanged(j);}else{j={id:uid(),title:intake.title.trim()||'Untitled idea',role:view==='solo'?selectedRole:'full',fields:clone(intake),originalInputs:clone(intake),createdAt:now(),updatedAt:now(),status:'Draft',progress:'Not started',archived:false,versions:[],output:'',review:{}};ws.jobs.unshift(j);editJob=j.id;}log('Saved content draft',j.id);persist();toast('Draft saved. No agent has run.');if(open||handoff){show('detail',{job:j.id});if(handoff)openPrompt(j.id);}}
function snapshot(j){j.versions??=[];j.versions.push({id:uid(),number:j.versions.length+1,createdAt:now(),fields:clone(j.fields||{}),output:j.output||'',status:j.status,review:clone(j.review||{}),approvedBy:j.approvedBy||'',approvedAt:j.approvedAt||'',postEvidence:clone(j.postEvidence||{})});}
function jobCard(j){return`<article class="job-card"><div class="row"><div><h3>${esc(j.title)}</h3>${badge(j.status)} <span class="badge">${esc(j.progress)}</span></div>${button('Open ↗','open-job',j.id,'small')}</div><div class="job-meta"><span>${esc(getRole(j.role))}</span><span>${esc(getMode(j.fields?.mode))}</span><span>${esc(j.fields?.source||'New idea')}</span></div><div class="job-meta"><span>@promptlikeglam</span><span>${esc(j.fields?.length||'Length open')}</span><span>CTA: ${esc(j.fields?.cta||'None')}</span><span>${esc(j.fields?.presentation||'Not applicable')}</span></div><div class="job-meta"><span>Updated ${esc(dateText(j.updatedAt))}</span><span>${j.fields?.date?'Plan: '+esc(j.fields.date):'No date planned'}</span><span>Next: ${j.status==='Draft'?'prepare a handoff':j.status==='Needs Review'?'review current version':j.status==='Ready'?'separate posting approval':'keep evidence with this version'}</span></div>${!j.fields?.sourceText&&!j.fields?.sourceFacts?'<div class="job-meta warn-text">Source context not supplied. Claims need checking.</div>':''}</article>`;}
function queueView(){let jobs=ws.jobs.filter(j=>filters.archive?j.archived:!j.archived).filter(j=>!filters.search||JSON.stringify([j.title,j.fields,j.output]).toLowerCase().includes(filters.search.toLowerCase())).filter(j=>!filters.status||j.status===filters.status).filter(j=>!filters.role||j.role===filters.role).filter(j=>!filters.mode||j.fields?.mode===filters.mode).filter(j=>!filters.source||j.fields?.source===filters.source).filter(j=>!filters.date||j.fields?.date===filters.date).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return heading('QUEUE & REVIEW','Keep the next step clear.','Content status and task progress are separate. Ready never means posted.',button('New content','new-content','','primary'))+`<div class="filters"><input aria-label="Search queue" id="search-queue" type="search" placeholder="Search your jobs…" value="${esc(filters.search||'')}"><select data-filter="status" aria-label="Status filter"><option value="">All content states</option>${['Draft','Needs Review','Ready','Posted Verified'].map(x=>`<option ${filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select data-filter="role" aria-label="Role filter"><option value="">All roles</option><option value="full" ${filters.role==='full'?'selected':''}>All five roles</option>${ROLES.map(x=>`<option value="${x.id}" ${filters.role===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select data-filter="mode" aria-label="Mode filter"><option value="">All modes</option>${MODES.map(x=>`<option value="${x.id}" ${filters.mode===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select data-filter="source" aria-label="Source filter"><option value="">All sources</option>${sources.map(x=>`<option ${filters.source===x?'selected':''}>${x}</option>`).join('')}</select><input type="date" data-filter="date" aria-label="Planned date filter" value="${esc(filters.date||'')}"></div><div class="row" style="margin-bottom:15px"><span class="muted">${jobs.length} ${filters.archive?'archived':'active'} jobs</span><div class="actions">${button(filters.archive?'Show active':'Show archive','toggle-archive','','small')}${button('Export queue CSV','queue-csv','','small')}</div></div><div class="queue-list">${jobs.map(jobCard).join('')||empty('Nothing here yet.','Save an idea or try a different filter.','new-content','Create content')}</div>`;}
function detailView(){const j=ws.jobs.find(j=>j.id===currentJob);if(!j)return empty('Job not found.','Return to your queue.','go-queue','Open queue');return`<div class="detail-top"><div><button class="text-button" data-view="queue">← Back to queue</button><h2>${esc(j.title)}</h2><div class="job-meta"><span>${esc(getRole(j.role))}</span><span>${esc(getMode(j.fields.mode))}</span><span>${esc(j.id.slice(0,8))}</span><span>Current v${(j.versions?.length||0)+1}</span></div></div><div class="actions">${button('Edit inputs','edit-job',j.id)}${button('Chat about this job','ai-job',j.id,'primary')}${button('Run in Chat ↗','run-chat',j.id)}</div></div><div class="detail-layout"><section class="stack"><div class="panel"><div class="row"><h3>Returned work</h3>${badge(j.status)}</div><p>Paste the actual result from your agent chat, or write it here. Use AI Chat to draft and revise, or paste work from another tool. Review before approving.</p><textarea id="job-output" class="output-area mt" placeholder="Paste your hooks, script, shot plan, caption, or finished package here…">${esc(j.output||'')}</textarea><div class="actions mt">${button('Save new version','save-output',j.id,'primary')}${button('Copy output','copy-output',j.id)}${button('Download TXT','download-job',j.id)}</div></div><div class="panel"><div class="row"><h3>Version history</h3><span class="badge">Originals preserved</span></div>${(j.versions||[]).length?(j.versions||[]).slice().reverse().map(v=>`<div class="history-item row"><span>v${v.number} · ${esc(v.status)}<br><small>${esc(dateText(v.createdAt))}</small></span><div class="actions">${button('View','view-version',j.id+'|'+v.id,'small')}${button('Restore as new','restore-version',j.id+'|'+v.id,'small')}</div></div>`).join(''):'<p>No earlier versions yet. Saving edits preserves the previous version here.</p>'}</div></section><section class="stack"><div class="panel"><h3>Review this version</h3><p>Approval applies to this wording and purpose only. It does not authorize posting or sending.</p><div class="checklist">${[['facts','Facts and source claims checked'],['rights','Rights and disclosures checked'],['clarity','Wording, captions, and spelling checked'],['cta','CTA and product details checked'],['assets','Assets and references checked']].map(([key,label])=>`<label class="check"><input type="checkbox" data-review="${key}" ${j.review?.[key]?'checked':''}>${label}</label>`).join('')}</div><div class="actions">${button('Needs review','needs-review',j.id,'small')}${button('Approve as Ready','approve-job',j.id,'primary')}</div><div class="mt"><label class="field">Task progress<select id="job-progress">${['Not started','In progress','Awaiting me','Blocked','Complete'].map(x=>`<option ${j.progress===x?'selected':''}>${x}</option>`).join('')}</select></label></div>${j.approvedAt?`<p>Current approval: ${esc(j.approvedBy)} · ${esc(dateText(j.approvedAt))}</p>`:''}</div><div class="panel"><h3>Posting evidence</h3><p>Manual verification only. Exporting or marking Ready does not publish anything.</p>${j.postEvidence?.url?`<p><a class="link safe-wrap" href="${esc(safeURL(j.postEvidence.url))}" target="_blank" rel="noopener">View recorded post ↗</a><br>${esc(j.postEvidence.account)} · ${esc(dateText(j.postEvidence.checkedAt))}<br>Recorded version: ${esc(j.postEvidence.version)}</p>`:''}<div class="mt">${button('Record verified post','post-evidence',j.id,'small')}</div></div><div class="panel"><h3>Saved context</h3><div class="info-list mt"><div><strong>TAKEAWAY</strong>${esc(j.fields.takeaway||'Not supplied')}</div><div><strong>SOURCE / RIGHTS</strong><div class="preserve">${esc(j.fields.sourceText||'Not supplied')}</div>${esc(j.fields.rights||'Needs checking')}</div><div><strong>ASSETS TO ATTACH MANUALLY</strong>${esc(j.fields.assetRefs||'No file references supplied')}</div><div><strong>CTA</strong>${esc(j.fields.cta||'No CTA')}</div></div><div class="actions mt">${button('View original inputs','original-inputs',j.id,'small')}${button(j.archived?'Unarchive job':'Archive job','archive-job',j.id,'small')}</div></div></section></div>`;}
function openPrompt(id){const j=ws.jobs.find(j=>j.id===id);if(!j)return;const text=buildPrompt(j,ws,j.role);modal('Run in Chat',`<div class="notice">Copy this into your agent chat. Nothing runs automatically. Attach any listed files yourself.</div><textarea id="handoff-prompt" class="mt" readonly>${esc(text)}</textarea><div class="modal-foot">${button('Copy prompt','copy-prompt',id,'primary')}${button('Download prompt TXT','download-prompt',id)}${button('Save to prompt vault','save-prompt',id)}${safeURL(ws.brand.agentLink)?`<a class="btn" href="${esc(safeURL(ws.brand.agentLink))}" target="_blank" rel="noopener">Open existing agent ↗</a>`:''}</div><p class="form-note mt">Opening an agent is a separate handoff. It does not transfer file bytes or grant posting, messaging, or spending permission.</p>`);}
function brandForm(){return`<form id="brand-form" class="panel"><div class="form-grid">${[['account','TikTok account'],['displayName','Display name'],['audience','Audience'],['voice','Voice and tone'],['terminology','Approved terminology'],['examples','Your voice examples'],['productFacts','Supported product facts only'],['productLink','Glam Vault public sales link'],['agentLink','Existing posting-agent chat link']].map(([k,l])=>`<label class="field ${['examples','productFacts'].includes(k)?'wide':''}">${l}${['examples','productFacts'].includes(k)?`<textarea name="${k}">${esc(ws.brand[k]||'')}</textarea>`:`<input name="${k}" value="${esc(ws.brand[k]||'')}">`}</label>`).join('')}</div><p class="form-note mt">This stores draft context, not new product claims or account settings. Changing this link does not change prices, policies, or customer access. Never add passwords or API keys.</p><div class="actions mt">${button('Save context','save-brand','','primary')}</div></form>`;}
function vaultView(){const tabs=[['brand','Brand context'],['content','My content'],['prompts','Saved prompts'],['approved','Approved copy'],['characters','Character refs']];let body='';if(subtab==='brand')body=brandForm();if(subtab==='content')body=`<div class="notice">References only. Your original videos and images stay where they are. Backups contain metadata, not media bytes.</div><div class="section-title"><h2>Original content & asset references</h2>${button('Add reference','add-asset','','primary')}</div><div class="compact-list">${ws.assets.map(a=>`<article class="content-ref"><div class="row"><h3>${esc(a.title||a.filename)}</h3><span class="tag">${esc(a.kind||'REFERENCE')}</span></div><p class="preserve">${esc(a.source)}</p><p>${esc(a.rights)} · ${esc(a.filename||'No local file')} · ${esc(a.format||'Format not set')}</p><small>Added ${esc(dateText(a.createdAt))} · ${esc(a.attachmentAvailability||'Attach manually in chat')}</small>${safeURL(a.source)?`<div class="mt"><a class="btn small" href="${esc(safeURL(a.source))}" target="_blank" rel="noopener">Open reference ↗</a></div>`:''}</article>`).join('')||empty('Keep the originals close.','Add a link, filename, transcript reference, or idea. We do not upload or alter the original.','add-asset','Add your first reference')}</div>`;if(subtab==='prompts')body=`<div class="section-title" style="margin-top:0"><h2>Your reusable handoffs</h2>${button('New saved prompt','new-prompt','','primary')}</div><div class="compact-list">${ws.prompts.map(p=>`<article class="content-ref"><div class="row"><h3>${esc(p.title)}</h3><span class="badge">v${esc(p.version)}</span></div><p>${esc(p.purpose||getRole(p.role))}</p><small>${esc(dateText(p.createdAt))} · ${esc(p.variables||'No variables specified')}</small><div class="actions mt">${button('View / edit','edit-prompt',p.id,'small')}${button('Copy','copy-saved',p.id,'small')}${button('Duplicate','duplicate-prompt',p.id,'small')}${button('Export TXT','export-saved',p.id,'small')}</div></article>`).join('')||empty('A home for prompts worth keeping.','Save a Run in Chat prompt from any job, or write your own.','new-prompt','Write a saved prompt')}</div>`;if(subtab==='approved'){const entries=[];ws.jobs.forEach(j=>{if(j.approvedAt)entries.push({j,v:{output:j.output,approvedAt:j.approvedAt,approvedBy:j.approvedBy,number:(j.versions?.length||0)+1}});(j.versions||[]).filter(v=>v.approvedAt).forEach(v=>entries.push({j,v}));});body=`<div class="notice">Wording approved for a stated job, not standing permission to post or send. Earlier approved snapshots remain here after edits.</div><div class="compact-list mt">${entries.map(({j,v})=>`<article class="content-ref"><h3>${esc(j.title)} · v${v.number}</h3><p>Approved by ${esc(v.approvedBy)} · ${esc(dateText(v.approvedAt))}</p><p class="preserve">${esc((v.output||'').slice(0,400))}${(v.output||'').length>400?'…':''}</p>${button('Open source job','open-job',j.id,'small')}</article>`).join('')||empty('No approved copy yet.','Review a content package and approve its current version when it is ready.','go-queue','Open queue')}</div>`;}if(subtab==='characters')body=`<div class="notice">Optional, never required. A locked character needs both references and your approval. Reference paths are not file attachments.</div><div class="section-title"><h2>Recurring character references</h2>${button('Add character','add-character','','primary')}</div>${ws.characters.map(c=>`<article class="content-ref"><div class="row"><h3>${esc(c.name)}</h3><span class="badge">${c.approved&&c.slot1&&c.slot2?'Locked by owner':'Unapproved reference'}</span></div><p>Slot 1 / headshot: ${esc(c.slot1||'Missing')}<br>Slot 2 / front, profile, three-quarter sheet: ${esc(c.slot2||'Missing')}</p><p>${esc(c.voice)}</p><small>Attach originals separately. Written prompts cannot guarantee identity consistency.</small></article>`).join('')||empty('No forced avatar here.','Screen recordings and tutorials can work without a character. Add one only when useful.','add-character','Add optional references')}`;return heading('GLAM CONTENT VAULT','Keep the good stuff.','Your context, original references, and reusable work. This is separate from the paid Glam Vault product.')+`<div class="tabs">${tabs.map(([id,name])=>`<button class="tab ${subtab===id?'active':''}" data-action="vault-tab" data-id="${id}">${name}</button>`).join('')}</div>${body}`;}
function engagementView(){return heading('ENGAGEMENT & VAULT','A thoughtful reply starts here.','Capture only the context you need. This is a manual workspace, not a live inbox.')+`<div class="notice warning row"><span><strong>Draft mode / Sending disabled.</strong> No listener, automatic replies, or comment-to-DM connection.</span><span class="tag">MANUAL ONLY</span></div><div class="two-col mt"><form id="engagement-form" class="panel"><h2>Capture an incoming message</h2><p>No passwords, payment details, or sensitive private information.</p><div class="form-grid mt"><label class="field">Sender handle<input name="sender" placeholder="@theirhandle" required></label><label class="field">Message type<select name="type"><option>DM</option><option>Comment</option></select></label><label class="field wide">Exact incoming text<textarea name="text" required placeholder="Paste the relevant message…"></textarea></label><label class="field">Event ID, if available<input name="eventId" placeholder="Helps prevent duplicate drafts"></label><label class="field">Message time<input name="eventTime" type="datetime-local"></label><label class="field wide">Source reference<input name="source" placeholder="Link or minimal source note"></label><label class="check field wide"><input type="checkbox" name="previousUncertain">An earlier send may have happened, but I have not verified it.</label></div><div class="actions mt">${button('Prepare reply draft','prepare-reply','','primary')}${button('Edit draft templates','reply-templates')}</div></form><section class="stack"><div class="panel"><h3>VAULT invitations, without assumptions.</h3><p>Public CTA draft:</p><div class="draft-message mt">Want the Glam Vault details? DM me VAULT.</div><p>A keyword is only a signal. Stop requests, duplicates, unclear intent, complaints, and uncertain sends are held for your review.</p><p>Native keyword eligibility is unverified. A saved link is not a connection.</p><a class="btn small mt" href="https://www.tiktok.com/business-suite/messages?lang=en&from=homepage" target="_blank" rel="noopener">Open TikTok inbox manually ↗</a></div><div class="panel"><h3>Promotional suppression</h3><p>${ws.suppression.length} sender${ws.suppression.length===1?'':'s'} currently held after a stop request. A later keyword does not automatically remove this hold.</p>${ws.suppression.length?`<p class="safe-wrap">${ws.suppression.map(s=>esc(typeof s==='string'?s:s.sender||'Recorded sender')).join(', ')}</p>`:''}</div></section></div><div class="section-title"><h2>Your reply work</h2><span class="muted">${ws.engagement.length} records</span></div><div class="queue-list">${ws.engagement.map(e=>`<article class="job-card"><div class="row"><h3>${esc(e.sender)} · ${esc(e.type)}</h3>${badge(e.state)}</div><p class="muted preserve mt">${esc(e.text)}</p><p class="form-note mt">${esc(e.reason||'Manual review required.')}</p>${e.draft?`<div class="draft-message mt">${esc(e.draft)}</div>`:''}<div class="actions mt">${button('Review draft','review-reply',e.id,'small')}${e.draft?button('Copy reply','copy-reply',e.id,'small'):''}</div><div class="job-meta"><span>${esc(dateText(e.createdAt))}</span><span>${e.evidence?'Evidence recorded':'No verified send'}</span></div></article>`).join('')||empty('No messages captured.','Paste a real incoming comment or DM above. Nothing is fetched or sent automatically.','','')}</div>`;}
function settingsView(){return heading('SETTINGS & CONNECTIONS','Clear about what’s connected.','Your data stays in this browser. Private hosting is not a cloud backup or cross-device sync.')+`<div class="two-col"><section class="stack"><div class="panel"><h2>Storage & backup</h2><p>Jobs, prompts, and references are saved on this device, in this browser. Clearing site data can erase them. Export regular JSON backups.</p><div class="notice mt">Backups contain text and metadata only. Original media stays in its original location and must be backed up separately.</div><div class="actions mt">${button('Export workspace JSON','export-workspace','','primary')}${button('Import backup','import-backup')}</div>${storageError?`<div class="mt">${button('Export raw recovery copy','raw-recovery','','danger')}</div>`:''}<p>Imports are previewed and merged. Exact duplicates are skipped; changed records are added as copies, never silently overwritten.</p><div class="actions mt">${button('Export queue CSV','queue-csv','','small')}${button('Download quick guide','download-guide','','small')}</div></div><div class="panel"><h3>Approved destinations</h3><p>Sales link: <a class="link safe-wrap" href="${esc(safeURL(ws.brand.productLink)||'https://payhip.com/b/54LoK')}" target="_blank" rel="noopener">${esc(ws.brand.productLink||'https://payhip.com/b/54LoK')}</a></p><p>Existing agent links are handoffs only, not integrations.</p><button class="btn small mt" data-action="brand-settings">Edit brand context & links</button></div><div class="panel"><h3>Media backup checklist</h3>${ws.assets.length?ws.assets.map(a=>`<div class="history-item"><strong>${esc(a.filename||a.title)}</strong><br><small>${esc(a.source)} · ${esc(a.attachmentAvailability||'Reference only; original not included')}</small></div>`).join(''):'<p>No media references yet. This app does not upload or embed your original files.</p>'}</div></section><section class="stack"><div class="panel"><h2>Capability status</h2>${[['Content drafting','AI Chat available','Secure server-side AI; existing API balance applies. No automatic credit purchases. Manual handoffs remain available.'],['TikTok reading','Not connected','This dashboard has no authorized account-reading connection.'],['Posting','Not connected','Separate approval and a verified posting method required.'],['Incoming DM events','Not connected','No listener or background polling.'],['Sending replies','Needs permission','Sending is disabled. Review and copy drafts for manual use.'],['Native keyword automation','Unverified','Eligibility, trigger rules, safeguards, and account permissions must be checked.']].map(([name,status,note])=>`<div class="connection"><div>${name}<small>${note}</small></div><span class="badge">${status}</span></div>`).join('')}<p>Prior observation: @promptlikeglam’s Business Suite Messages and Comments were visible on October 24, 2026, Eastern time, in a separate browser session. That does not connect this app or prove sending permission.</p></div><div class="panel"><h3>Recent workspace activity</h3>${ws.activity.slice(0,8).map(a=>`<div class="history-item">${esc(a.action)}<br><small>${esc(dateText(a.time))} · ${esc(a.result)}</small></div>`).join('')||'<p>Your own saved actions will appear here.</p>'}</div></section></div>`;}
const GUIDE=`GLAM TIKTOK AGENT FARM\n\nYour first content job\n1. Choose Create content, add a title and an idea, then Save draft. Incomplete drafts are fine.\n2. Open the job and choose Run in Chat. Copy the prompt into your existing agent conversation and attach the listed files yourself.\n3. Paste the real returned result into Returned work. Save a new version, complete the review checks, and approve as Ready.\n\nNothing runs, posts, schedules, or sends automatically. Ready approves wording for this job only.\n\nStorage\nThis workspace uses this browser's local storage. It does not sync across devices. Export workspace JSON in Settings regularly. Your backup includes text and metadata, not original media. References show which originals need separate backup. Imports preview and merge, preserving existing records.\n\nVAULT\nSending is disabled. Draft replies from actual context, review intent, and honor suppression. Native keyword features are unverified. Recorded sent or posted evidence is manually supplied by you, not a live API verification.\n\nPrivacy\nKeep secrets and sensitive personal details out of this workspace. API credentials stay on the server. AI Chat uses the existing API balance; no credits are purchased automatically. There is no live TikTok connection or automatic listening. Original files remain untouched.\n`;
function outputChanged(j){j.status='Needs Review';j.review={};delete j.approvedAt;delete j.approvedBy;delete j.postEvidence;j.updatedAt=now();}
function promptEditor(p=null){modal(p?'Edit saved prompt':'Create saved prompt',`<form id="prompt-form"><div class="form-grid"><label class="field">Title<input name="title" value="${esc(p?.title||'')}" required></label><label class="field">Role<select name="role"><option value="full">All five roles</option>${ROLES.map(r=>`<option value="${r.id}" ${p?.role===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label class="field">Purpose<input name="purpose" value="${esc(p?.purpose||'')}"></label><label class="field">Editable variables<input name="variables" value="${esc(p?.variables||'')}" placeholder="e.g. [topic], [audience]"></label><label class="field wide">Prompt text<textarea name="text" required>${esc(p?.text||'')}</textarea></label></div><p class="form-note mt">Changes preserve earlier versions. A saved prompt never grants external-action permission.</p><div class="modal-foot">${button('Save prompt version','commit-prompt',p?.id||'','primary')}</div></form>${p?.previousVersions?.length?`<details class="mt"><summary>${p.previousVersions.length} earlier version(s)</summary>${p.previousVersions.map(v=>`<p class="preserve history-item">v${v.version} · ${esc(dateText(v.createdAt))}<br>${esc(v.text)}</p>`).join('')}</details>`:''}`);}
function replyEditor(id){const e=ws.engagement.find(e=>e.id===id);modal(`Review reply to ${e.sender}`,`<div class="notice warning">Sending stays disabled. Approval applies only to this exact draft and recipient. Sent Verified requires evidence from a real manual send.</div><p class="preserve mt"><strong>Incoming context</strong><br>${esc(e.text)}</p><p class="form-note mt">${esc(e.reason)}</p><form id="reply-form" class="mt"><label class="field">Exact outgoing draft<textarea name="draft">${esc(e.draft||'')}</textarea></label><div class="split-small mt"><label class="field">Reply state<select name="state">${['Draft','Needs Review','Approved for this action','Sent Verified','Failed','Needs Human'].map(s=>`<option ${e.state===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Authorization reference<input name="authorization" value="${esc(e.authorization||'')}" placeholder="Exact action and recipient approval"></label></div><label class="field mt">Actual send evidence / source reference<input name="evidence" value="${esc(e.evidence||'')}" placeholder="Message URL or real platform message ID and observation time"></label><label class="check mt"><input name="checked" type="checkbox">I personally checked the exact recipient, text, and successful send in the platform.</label><div class="modal-foot">${button('Save reply review','save-reply',id,'primary')}${button('Copy draft','copy-reply',id)}</div></form>`);}
function importPreview(data){const lists=['jobs','prompts','assets','characters','engagement'];let exact=0,conflicts=0,newCount=0;lists.forEach(k=>data[k].forEach(r=>{let existing=ws[k].find(x=>x.id===r.id);if(!existing)newCount++;else if(JSON.stringify(existing)===JSON.stringify(r))exact++;else conflicts++;}));pendingImport=data;modal('Preview backup import',`<div class="notice">Nothing has changed yet. Existing work and original files will not be overwritten.</div><div class="numbers"><div class="number"><strong>${newCount}</strong><span>NEW RECORDS</span></div><div class="number"><strong>${exact}</strong><span>DUPLICATES TO SKIP</span></div><div class="number"><strong>${conflicts}</strong><span>CONFLICT COPIES</span></div></div><p class="form-note mt">${ws.jobs.length+ws.prompts.length+ws.assets.length+ws.characters.length+ws.engagement.length===0?'This empty workspace will also restore the backup’s brand context and draft templates.':'Existing brand context and templates stay unchanged.'} Suppression holds are merged conservatively. Media bytes are not included.</p><div class="modal-foot">${button('Merge backup','merge-import','','primary')}${button('Cancel','close-dialog')}</div>`);}
function mergeImport(){if(!pendingImport)return;const data=pendingImport,emptySpace=!['jobs','prompts','assets','characters','engagement'].some(k=>ws[k].length);if(emptySpace){ws.brand=clone(data.brand);ws.settings=clone(data.settings||{});}let added=0;const remap=new Map();for(const k of ['jobs','prompts','assets','characters','engagement'])for(const r of data[k]){const old=ws[k].find(x=>x.id===r.id);if(old&&JSON.stringify(old)!==JSON.stringify(r))remap.set(r.id,uid());}for(const k of ['jobs','prompts','assets','characters','engagement']){for(const r of data[k]){const existing=ws[k].find(x=>x.id===r.id);if(existing&&JSON.stringify(existing)===JSON.stringify(r))continue;const item=clone(r);if(item.sourceJob&&remap.has(item.sourceJob))item.sourceJob=remap.get(item.sourceJob);if(item.derivativeOf&&remap.has(item.derivativeOf))item.derivativeOf=remap.get(item.derivativeOf);if(existing){item.id=remap.get(r.id);if(item.title)item.title+=' (imported copy)';if(k==='engagement'){item.state='Needs Human';item.reason='Imported conflict copy. Check send history before any reply.';}}ws[k].push(item);added++;}}for(const rec of data.activity||[]){const previous=ws.activity.find(x=>x.id===rec.id);if(previous&&JSON.stringify(previous)===JSON.stringify(rec))continue;const copy=clone(rec);if(previous)copy.id=uid();if(remap.has(copy.itemId))copy.itemId=remap.get(copy.itemId);ws.activity.push(copy);}ws.suppression=[...new Set([...ws.suppression,...data.suppression])];for(const e of ws.engagement){if(ws.suppression.some(s=>String(s).toLowerCase().replace(/^@/,'')===String(e.sender).toLowerCase().replace(/^@/,''))&&!['Sent Verified','Failed'].includes(e.state)){e.suppressed=true;e.state='Needs Human';e.draft='';e.reason='Suppression hold restored. No promotional reply.';}}pendingImport=null;log('Merged backup','',`${added} records added`);persist();closeModal();show('settings');toast(`Backup merged. ${added} records added; existing work preserved.`);}
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>8*1024*1024)throw Error('Backup exceeds the 8 MB import limit.');const data=validateImport(JSON.parse(await f.text()),ws);importPreview(data);}catch(err){toast(`Import rejected: ${err.message}`);}finally{e.target.value='';}});

let aiJob='',aiMessages=[],aiDraft='',aiBusy=false,aiError='';
function aiChatView(){const j=ws.jobs.find(j=>j.id===aiJob);return heading('YOUR CREATIVE ASSISTANT','AI Chat','Draft, ask follow-up questions, then save the answer you choose.')+`<div class="panel stack"><label class="field">Job context<select id="ai-job-select" ${aiBusy?'disabled':''}><option value="">General chat — no job</option>${ws.jobs.filter(j=>!j.archived).map(j=>`<option value="${esc(j.id)}" ${j.id===aiJob?'selected':''}>${esc(j.title)}</option>`).join('')}</select></label><p class="form-note">${j?'Only this job’s prepared prompt and this conversation are sent.':'Only this conversation is sent.'} AI uses your existing API balance. No credit purchases. References are not uploaded files; this chat does not browse the web or post to TikTok.</p><div aria-live="polite" class="ai-transcript">${aiMessages.map(m=>`<article class="history-item"><strong>${m.role==='user'?'You':'Glam AI'}</strong><div class="preserve">${esc(m.content)}</div></article>`).join('')||'<p>Ask for hooks, scripts, captions, or help improving an idea.</p>'}${aiBusy?'<p role="status">Writing your answer…</p>':''}</div>${aiError?`<div role="alert" class="notice danger">${esc(aiError)} ${aiError.includes('Sign in')?'<a href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT</a>':''}</div>`:''}<label class="field">Your message<textarea id="ai-message" maxlength="6000" ${aiBusy?'disabled':''} placeholder="Help me turn this idea into a useful TikTok…">${esc(aiDraft)}</textarea></label><div class="actions"><button class="btn primary" data-action="ai-send" ${aiBusy?'disabled':''}>${aiBusy?'Working…':'Send to AI'}</button><button class="btn" data-action="ai-copy" ${aiBusy||!aiMessages.some(m=>m.role==='assistant')?'disabled':''}>Copy latest answer</button><button class="btn" data-action="ai-save" ${aiBusy||!j||!aiMessages.some(m=>m.role==='assistant')?'disabled':''}>Save answer as job version</button><button class="btn" data-action="ai-clear" ${aiBusy?'disabled':''}>New chat</button></div><p class="form-note">Chat stays in this tab until reload. Save useful answers to a job or copy them. Existing output is preserved as an earlier version.</p></div>`;}
async function sendAI(){if(aiBusy)return;const input=$('#ai-message');const question=input?.value.trim();if(!question){toast('Type a message first.');return;}if(question.length>6000){toast('Keep your message under 6,000 characters.');return;}aiDraft=question;aiError='';const j=ws.jobs.find(j=>j.id===aiJob),previous=aiMessages.slice(-4).map(m=>({...m,content:m.content.slice(0,4500)}));const messages=[...previous,{role:'user',content:question}];aiMessages.push({role:'user',content:question});aiBusy=true;aiDraft='';render();try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages,context:j?buildPrompt(j,ws,j.role).slice(0,16000):''}),signal:AbortSignal.timeout(95000)});const data=await r.json();if(!r.ok)throw Error(data.error||'AI request failed.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('No answer returned.');aiMessages.push({role:'assistant',content:data.answer});}catch(e){aiMessages.pop();aiDraft=question;aiError=e.name==='TimeoutError'?'The request timed out. Your message is ready to retry.':e.message;}finally{aiBusy=false;if(view==='chat')render();}}
function saveAI(){const j=ws.jobs.find(j=>j.id===aiJob),answer=aiMessages.filter(m=>m.role==='assistant').at(-1);if(!j||!answer)return;if(storageError){toast('Resolve the storage warning before saving.');return;}if(j.output===answer.content){toast('This answer is already saved.');return;}snapshot(j);j.output=answer.content;outputChanged(j);j.progress='Awaiting me';log('Saved AI draft for review',j.id);if(persist())toast('Saved as a new job version. Earlier work is preserved.');}
document.addEventListener('input',e=>{if(e.target.id==='ai-message')aiDraft=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='ai-job-select'){if(aiBusy)return;aiJob=e.target.value;aiMessages=[];aiError='';render();}});

document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-view]');if(!b)return;if(b.dataset.view){show(b.dataset.view);return;}const a=b.dataset.action,id=b.dataset.id,j=ws.jobs.find(j=>j.id===id);try{
if(a==='ai-job'){if(aiBusy){toast('Wait for the current answer.');return;}aiJob=id;aiMessages=[];aiError='';show('chat');}
else if(a==='ai-send'){await sendAI();}
else if(a==='ai-save'){saveAI();}
else if(a==='ai-copy'){const answer=aiMessages.filter(m=>m.role==='assistant').at(-1);if(answer)await copy(answer.content);}
else if(a==='ai-clear'){if(aiBusy)return;if(await window.__ask('Clear this chat? Saved job versions stay unchanged.')){aiMessages=[];aiDraft='';aiError='';render();}}
else if(a==='close-dialog'){closeModal();pendingImport=null;}
else if(a==='new-content'){show('intake',{fresh:true});}
else if(a==='go-queue')show('queue');
else if(a==='form-step'){intake={...intake,...collect($('#job-form'))};formStep=Number(id);render();$('#main').scrollTop=0;}
else if(a==='select-role'){if($('#job-form'))intake={...intake,...collect($('#job-form'))};selectedRole=id;editJob=null;render();}
else if(a==='save-job')saveJob();else if(a==='save-open')saveJob(true);else if(a==='save-handoff')saveJob(false,true);
else if(a==='open-job')show('detail',{job:id});
else if(a==='edit-job'){editJob=id;intake=clone(j.fields);formStep=0;if(j.role!=='full'){selectedRole=j.role;view='solo';}else view='intake';render();}
else if(a==='run-chat')openPrompt(id);
else if(a==='copy-prompt'){await copy($('#handoff-prompt').value);toast('Prompt copied. Nothing is running automatically.');}
else if(a==='download-prompt')download(filename(j.title+'-prompt'),$('#handoff-prompt').value);
else if(a==='save-prompt'){ws.prompts.unshift({id:uid(),title:j.title+' / handoff',purpose:getRole(j.role),role:j.role,variables:'',text:$('#handoff-prompt').value,version:1,sourceJob:j.id,createdAt:now(),previousVersions:[]});log('Saved reusable prompt',j.id);persist();toast('Saved in Content vault → Saved prompts.');}
else if(a==='save-output'){const output=$('#job-output').value;if(output===j.output){toast('No changes to save.');return;}snapshot(j);j.output=output;outputChanged(j);j.progress='Awaiting me';log('Saved output version',j.id);persist();render();toast('New version saved. Review checks reset.');}
else if(a==='copy-output')await copy($('#job-output')?.value??j.output);
else if(a==='download-job')download(filename(j.title),`${j.title}\nAccount: @promptlikeglam\nContent status: ${j.status}\nTask progress: ${j.progress}\nVersion: ${(j.versions?.length||0)+1}\n\nORIGINAL INPUTS\n${JSON.stringify(j.originalInputs,null,2)}\n\nCURRENT INPUTS\n${JSON.stringify(j.fields,null,2)}\n\nRETURNED OUTPUT\n${j.output||'No returned output saved.'}\n\nEVIDENCE\n${JSON.stringify(j.postEvidence||{},null,2)}\n\nNo media bytes included. This export does not authorize posting or sending.`);
else if(a==='needs-review'){if(j.status==='Ready'||j.status==='Posted Verified')snapshot(j);outputChanged(j);log('Marked needs review',id);persist();render();}
else if(a==='approve-job'){if($('#job-output').value!==j.output){toast('Save your output changes before approving.');return;}if(!j.output.trim()){toast('Save the returned content before approving.');return;}if(!['facts','rights','clarity','cta','assets'].every(k=>j.review?.[k])){toast('Complete all five review checks first.');return;}j.status='Ready';j.approvedBy='Workspace owner';j.approvedAt=now();j.updatedAt=now();log('Approved current content version',id);persist();render();toast('Ready for the stated purpose. Nothing was posted.');}
else if(a==='archive-job'){j.archived=!j.archived;j.updatedAt=now();log(j.archived?'Archived job':'Restored archived job',id);persist();show('queue');}
else if(a==='toggle-archive'){filters.archive=!filters.archive;render();}
else if(a==='view-version'||a==='restore-version'){const [jid,vid]=id.split('|'),job=ws.jobs.find(x=>x.id===jid),v=job.versions.find(x=>x.id===vid);if(a==='view-version')modal(`Version ${v.number}: ${job.title}`,`<p>${esc(v.status)} · ${esc(dateText(v.createdAt))}</p><textarea class="mt" readonly>${esc(v.output||'(No returned output in this version)')}</textarea><details class="mt"><summary>Saved input fields</summary><p class="preserve">${esc(JSON.stringify(v.fields,null,2))}</p></details>`);else{snapshot(job);job.fields=clone(v.fields);job.output=v.output;job.title=job.fields.title||job.title;outputChanged(job);log('Restored snapshot as new version',job.id);persist();render();toast('Restored as a new version. Earlier versions preserved.');}}
else if(a==='original-inputs')modal('Original inputs, preserved',`<p class="preserve">${esc(JSON.stringify(j.originalInputs,null,2))}</p>`);
else if(a==='post-evidence')modal('Record a post you verified',`<div class="notice warning">This does not post or check TikTok automatically. Record only the exact approved version you personally verified on @promptlikeglam.</div><form id="post-form" class="stack mt"><label class="field">Exact TikTok post permalink<input name="url" type="url" placeholder="https://www.tiktok.com/@promptlikeglam/video/…" required></label><label class="field">Destination account<input name="account" value="@promptlikeglam" required></label><label class="check"><input name="checked" type="checkbox">I checked this post, its account, and its content against this exact approved version.</label><div class="actions">${button('Record verified evidence','save-post-evidence',id,'primary')}</div></form>`);
else if(a==='save-post-evidence'){const f=collect($('#post-form')),u=safeURL(f.url);if(j.status!=='Ready'){toast('Approve this content version as Ready first.');return;}if(!f.checked||f.account!=='@promptlikeglam'||!/^https:\/\/(www\.)?tiktok\.com\/@promptlikeglam\/video\/\d+(?:\?.*)?$/.test(u)){toast('Use the exact @promptlikeglam TikTok video URL and confirm you checked it.');return;}j.postEvidence={url:u,account:f.account,checkedAt:now(),version:(j.versions?.length||0)+1};j.status='Posted Verified';j.updatedAt=now();log('Recorded manually verified post',id);persist();closeModal();render();toast('Manual verification evidence recorded.');}
else if(a==='vault-tab'){subtab=id;render();}
else if(a==='brand-settings')show('vault',{tab:'brand'});
else if(a==='save-brand'){const data=collect($('#brand-form'));if(data.productLink&&!safeURL(data.productLink)){toast('Enter a valid https or http product link.');return;}if(data.agentLink&&!safeURL(data.agentLink)){toast('Enter a valid agent link.');return;}ws.brand={...ws.brand,...data};log('Updated brand draft context');persist();toast('Context saved. No account or product settings changed.');}
else if(a==='add-asset')modal('Add a content reference',`<form id="asset-form"><div class="form-grid"><label class="field">Title<input name="title" required></label><label class="field">Kind<select name="kind"><option>Video</option><option>Image</option><option>Transcript</option><option>Idea</option><option>Caption</option><option>Research</option></select></label><label class="field wide">Original link, location, or pasted reference<textarea name="source" required></textarea></label><label class="field">Original filename, if relevant<input name="filename"></label><label class="field">Original format<input name="format" placeholder="JPG, PNG, MP4, TXT…"></label><label class="field">Rights / use notes<input name="rights" placeholder="Mine, licensed, or research only"></label><label class="field">Related original / derivative ID<input name="derivativeOf"></label><label class="field wide">Notes<textarea name="notes"></textarea></label></div><p class="form-note mt">No file is uploaded, modified, or copied. Keep originals and attach them separately to chats that need them.</p><div class="modal-foot">${button('Save reference','save-asset','','primary')}</div></form>`);
else if(a==='save-asset'){const f=$('#asset-form');if(!f.reportValidity())return;const x={id:uid(),...collect(f),createdAt:now(),attachmentAvailability:'Reference only. Attach original manually.'};ws.assets.unshift(x);log('Saved asset reference',x.id);persist();closeModal();render();toast('Reference saved. Original unchanged.');}
else if(a==='add-character')modal('Add optional character references',`<form id="character-form"><div class="form-grid"><label class="field">Character name / ID<input name="name" required></label><label class="field">Voice notes<input name="voice"></label><label class="field wide">Slot 1: headshot reference<input name="slot1" placeholder="Original JPG or PNG filename / reference"></label><label class="field wide">Slot 2: single reference sheet<input name="slot2" placeholder="One sheet with front, side/profile, and three-quarter views"></label><label class="check field wide"><input name="approved" type="checkbox">I approve both references as the locked identity.</label></div><p class="form-note mt">Preserve the original formats. No images upload or change here. A character locks only with both slots and your approval.</p><div class="modal-foot">${button('Save character','save-character','','primary')}</div></form>`);
else if(a==='save-character'){const f=$('#character-form');if(!f.reportValidity())return;const d=collect(f);if(d.approved&&(!d.slot1.trim()||!d.slot2.trim())){toast('Both reference slots are required to lock a character.');return;}ws.characters.unshift({id:uid(),...d,approved:!!d.approved,createdAt:now()});log('Saved optional character reference');persist();closeModal();render();}
else if(a==='new-prompt')promptEditor();else if(a==='edit-prompt')promptEditor(ws.prompts.find(p=>p.id===id));
else if(a==='commit-prompt'){const f=$('#prompt-form');if(!f.reportValidity())return;const d=collect(f),p=ws.prompts.find(p=>p.id===id);if(p){p.previousVersions??=[];p.previousVersions.push({text:p.text,version:p.version,createdAt:p.createdAt});Object.assign(p,d,{version:p.version+1,createdAt:now()});}else ws.prompts.unshift({id:uid(),...d,version:1,createdAt:now(),sourceJob:'',previousVersions:[]});log('Saved prompt version',id||'');persist();closeModal();render();}
else if(['copy-saved','export-saved','duplicate-prompt'].includes(a)){const p=ws.prompts.find(p=>p.id===id);if(a==='copy-saved')await copy(p.text);if(a==='export-saved')download(filename(p.title),p.text);if(a==='duplicate-prompt'){const q=clone(p);q.id=uid();q.title+=' (draft copy)';q.version=1;q.createdAt=now();q.previousVersions=[];ws.prompts.unshift(q);log('Duplicated prompt as draft',q.id);persist();render();}}
else if(a==='prepare-reply'){const f=$('#engagement-form');if(!f.reportValidity())return;const d={...collect(f),previousUncertain:!!f.elements.previousUncertain.checked};const outcome=evaluateReply(d,ws);if(outcome.suppressed){const s=d.sender.trim().toLowerCase();if(!ws.suppression.includes(s))ws.suppression.push(s);for(const item of ws.engagement.filter(x=>x.sender.toLowerCase().replace(/^@/,'')===s.replace(/^@/,''))){if(item.state!=='Sent Verified'){item.suppressed=true;item.state='Needs Human';item.reason='Explicit stop request. Promotional reply is on hold.';}}persist('Suppression saved');}const duplicate=ws.engagement.find(x=>outcome.dedupeKey&&x.dedupeKey===outcome.dedupeKey);if(duplicate){toast('This event already exists. Review its existing record; no duplicate draft was added.');replyEditor(duplicate.id);return;}const item={id:uid(),...d,createdAt:now(),updatedAt:now(),draft:outcome.text||'',state:outcome.state||'Needs Review',reason:outcome.reason||'',dedupeKey:outcome.dedupeKey,suppressed:outcome.suppressed||false,version:1,previousVersions:[],authorization:'',evidence:''};ws.engagement.unshift(item);log('Prepared manual reply review',item.id);persist();render();toast('Draft prepared for review. Nothing sent.');}
else if(a==='review-reply')replyEditor(id);else if(a==='copy-reply'){const item=ws.engagement.find(x=>x.id===id);if(item.suppressed||ws.suppression.some(s=>s.toLowerCase().replace(/^@/,'')===item.sender.toLowerCase().replace(/^@/,''))){toast('This sender is suppressed. Promotional copying is blocked.');return;}await copy($('#reply-form')?$('#reply-form').elements.draft.value:item.draft);}
else if(a==='save-reply'){const item=ws.engagement.find(x=>x.id===id),f=collect($('#reply-form'));const changed=f.draft!==item.draft;if((item.suppressed||ws.suppression.some(s=>s.toLowerCase().replace(/^@/,'')===item.sender.toLowerCase().replace(/^@/,'')))&&['Approved for this action','Sent Verified'].includes(f.state)){toast('This sender is suppressed. Promotional approval is blocked.');return;}if(item.previousUncertain&&f.state==='Approved for this action'){toast('Verify the earlier send outcome before approving another reply.');return;}if(f.state==='Sent Verified'&&(!f.checked||!f.evidence.trim()||!f.authorization.trim()||!f.draft.trim())){toast('Record authorization and actual successful-send evidence, then confirm you checked it.');return;}if(f.state==='Approved for this action'&&(!f.authorization.trim()||!f.draft.trim())){toast('Add the exact authorization reference and draft text.');return;}if(changed){item.previousVersions.push({draft:item.draft,state:item.state,version:item.version,createdAt:now()});item.version++;if(['Approved for this action','Sent Verified'].includes(item.state)){f.state='Needs Review';f.evidence='';f.authorization='';}}Object.assign(item,{draft:f.draft,state:f.state,authorization:f.authorization,evidence:f.evidence,updatedAt:now()});log('Saved manual reply review',id);persist();closeModal();render();toast('Reply record saved. Nothing sent by this app.');}
else if(a==='reply-templates')modal('Editable draft templates',`<form id="templates-form"><label class="field">Incoming VAULT DM draft<textarea name="replyTemplate">${esc(ws.settings.replyTemplate||"Hey girl, I see you! Here's the Glam Vault you asked for: https://payhip.com/b/54LoK\nTake a look, and let me know if you have a question.")}</textarea></label><label class="field mt">Comment reply draft<textarea name="commentTemplate">${esc(ws.settings.commentTemplate||'Hey girl, I see you! If you want the Glam Vault details, send me VAULT in a DM.')}</textarea></label><p class="form-note mt">Drafts only. Do not add prices, promises, discounts, or unverified benefits. Editing templates enables no automation.</p><div class="modal-foot">${button('Save draft templates','save-templates','','primary')}</div></form>`);
else if(a==='save-templates'){ws.settings={...ws.settings,...collect($('#templates-form'))};log('Saved reply draft templates');persist();closeModal();toast('Draft templates saved. Sending remains disabled.');}
else if(a==='export-workspace')download(filename('glam-tiktok-workspace','json'),JSON.stringify(ws,null,2),'application/json');
else if(a==='raw-recovery')download(filename('glam-tiktok-recovery','txt'),localStorage.getItem(KEY)||'No saved data found.');
else if(a==='import-backup')$('#import-file').click();else if(a==='merge-import')mergeImport();
else if(a==='queue-csv'){const rows=[['Title','ID','Role','Mode','Status','Progress','Source','Planned date','Updated','Archived'],...ws.jobs.map(j=>[j.title,j.id,getRole(j.role),getMode(j.fields?.mode),j.status,j.progress,j.fields?.source||'',j.fields?.date||'',j.updatedAt,j.archived?'Yes':'No'])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');download(filename('glam-tiktok-queue','csv'),csv,'text/csv');}
else if(a==='download-guide')download(filename('glam-tiktok-quick-guide'),GUIDE);
else if(a==='how-it-works')modal('Five roles. Seven ways to create.',`<div class="notice">Run in Chat builds a detailed prompt. Copy it into your agent conversation, attach your files, then paste the real result back here.</div>${ROLES.map((r,i)=>`<div class="role-explain"><span>0${i+1}</span><div><strong>${esc(r.name)}</strong><p>${esc(r.description)}</p></div></div>`).join('')}<h3 class="mt">Your seven content modes</h3><ol class="modes-list mt">${MODES.map(m=>`<li><strong>${esc(m.name)}</strong><br>${esc(m.brief)}</li>`).join('')}</ol>`);
}catch(err){console.error(err);toast('That action could not finish: '+err.message);}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render();}if(e.target.dataset.review){const j=ws.jobs.find(x=>x.id===currentJob);if(!e.target.checked&&['Ready','Posted Verified'].includes(j.status)){snapshot(j);outputChanged(j);}j.review??={};j.review[e.target.dataset.review]=e.target.checked;persist('Review checks saved');}if(e.target.id==='job-progress'){const j=ws.jobs.find(x=>x.id===currentJob);j.progress=e.target.value;j.updatedAt=now();log('Updated task progress',j.id);persist();toast('Task progress saved. Content state unchanged.');}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search-queue'){const value=e.target.value,pos=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{filters.search=value;render();$('#search-queue')?.focus();$('#search-queue')?.setSelectionRange(pos,pos);},180);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeModal();});
window.addEventListener('beforeunload',e=>{if(view==='detail'){const j=ws.jobs.find(x=>x.id===currentJob);if($('#job-output')&&$('#job-output').value!==(j?.output||'')){e.preventDefault();e.returnValue='';}}});
render();
